SELECT COUNT(*)
FROM orders
WHERE account_id = #{accountId}

SELECT COUNT(*)
FROM orders
WHERE account_id = #{accountId}
  AND stock_code = #{stockCode}

SELECT id, account_id, stock_code, side, order_type, quantity, limit_price,
       filled_price, filled_quantity, total_amount, status, cancel_of_order_id, ordered_at
FROM orders
WHERE account_id = #{accountId}
  AND stock_code = #{stockCode}
ORDER BY ordered_at DESC
